%[text] # 
%%Inputs Section
permeateflow=10000; %m^3/day
seawatersalinity=35000; %mg/L
recovery=0.45; 
rejection=0.997;
temperature=298.15; %Degrees Kelvin
R=0.08314; %L*bar/mol*k
molarmassNaCl=58.44; %g/mol
nIons=2; %ions
pumpefficiency=0.8; %fraction
ERDefficiency=0.96; %fraction
pressuremargin=6; %bar

%%Balance Section
feedflow=permeateflow/recovery;
brineflow=feedflow-permeateflow;
permeatesalinity=(1-rejection)*seawatersalinity;
brinesalinity=(feedflow*seawatersalinity-permeateflow*permeatesalinity)/(brineflow);
%%Salt Check
saltin=feedflow*seawatersalinity/1000000; %tonnes/day
saltout=(permeateflow*permeatesalinity+brineflow*brinesalinity)/1000000; %tonnes/day
fprintf("Salt in: %.1f tonnes/day\n",saltin); %[output:9683db0d]
fprintf("Salt out: %.1f tonnes/day\n",saltout); %[output:23a71320]
%%Osmotic Pressure
feedosmP=osmoticPressure(seawatersalinity,temperature);
brineosmP=osmoticPressure(brinesalinity,temperature) %[output:303b9275]
fprintf("Feed Osmotic Pressure: %.1f bar\n",feedosmP) %[output:47fa7a60]
fprintf("Brine Osmotic Pressure: %.1f bar\n",brineosmP) %[output:4e382cf2]
%%Checks
feedflowCheck=22222;
fprintf("Feed Flow: %.1f,(check %.1f, diff %.1f)\n", feedflow,feedflowCheck,feedflow-feedflowCheck); %[output:55df01a4]
brineflowCheck=12222;
fprintf("Brine Flow: %.1f,(check %.1f, diff %.1f)\n", brineflow,brineflowCheck,brineflow-brineflowCheck); %[output:74116406]
permeatesalinityCheck=105;
fprintf("Permeate Salinity: %.1f,(check %.1f, diff %.1f)\n", permeatesalinity,permeatesalinityCheck,permeatesalinity-permeatesalinityCheck); %[output:47a21a75]
brinesalinityCheck=63550;
fprintf("Brine Salinity: %.1f,(check %.1f, diff %.1f)\n", brinesalinity, brinesalinityCheck, brinesalinity-brinesalinityCheck) %[output:83e4307b]
saltincheck=778;
fprintf("Salt In: %.1f, (check %.1f, diff %.1f)\n", saltin, saltincheck, saltin-saltincheck) %[output:66fdc07f]
saltoutcheck=778;
fprintf("Salt Out: %.1f, (check %.1f, diff %.1f)\n", saltout, saltoutcheck, saltout-saltoutcheck) %[output:1aaeda74]
feedosmPCheck=29.7;
fprintf("Feed Osmotic Pressure: %.1f, (check %.1f, diff %.1f)\n", feedosmP, feedosmPCheck, feedosmP-feedosmPCheck) %[output:3b186669]
brineosmPCheck=53.9;
fprintf("Brine Osmotic Pressure: %.1f, (check %.1f, diff %.1f)\n", brineosmP, brineosmPCheck, brineosmP-brineosmPCheck) %[output:477ae7c3]
%%Max Recovery 
rMax60=maxRecovery(60,seawatersalinity,temperature) %[output:225c6fae]
fprintf("Max recovery at 60 bar: %.1f%%\n", rMax60*100); %[output:9f39587a]

%%Energy Values
energy45NoERD=energyNoERD(60,0.45,pumpefficiency);
fprintf("Energy:%.2f kWh/m^3\n",energy45NoERD) %[output:1ca72f5b]
energy50NoERD=energyNoERD(68,0.5,pumpefficiency);
fprintf("Energy:%.2f kWh/m^3\n",energy50NoERD) %[output:02e6482b]
energy45ERD=energyERD(60,0.45,pumpefficiency,ERDefficiency);
fprintf("Energy:%.2f kWh/m^3\n",energy45ERD) %[output:62564cce]
energy50ERD=energyERD(68,0.5,pumpefficiency,ERDefficiency);
fprintf("Energy:%.2f kWh/m^3\n",energy50ERD) %[output:6e7091a1]

%%Recovery Sweep
rSweep=0.3:0.01:0.6;
feedflowSweep=permeateflow./rSweep;
brineflowSweep=feedflowSweep-permeateflow;
brinesalinitySweep=(feedflowSweep.*seawatersalinity-permeateflow*permeatesalinity)./(brineflowSweep);
brineosmPSweep = osmoticPressure(brinesalinitySweep,temperature);   
PreqSweep=brineosmPSweep+pressuremargin;

ENoERDSweep=energyNoERD(PreqSweep,rSweep,pumpefficiency);
EERDSweep=energyERD(PreqSweep,rSweep,pumpefficiency,ERDefficiency);

%%Energy vs Recovery Plot
plot(rSweep*100,ENoERDSweep) %[output:148a19c6]
hold on %[output:148a19c6]
plot(rSweep*100,EERDSweep) %[output:148a19c6]
xlabel("Recovery %") %[output:148a19c6]
ylabel("Specific Energy in kWh/m^3") %[output:148a19c6]
title("Pump Energy vs Recovery") %[output:148a19c6]
legend("No Energy Recovery", "With Energy Recovery") %[output:148a19c6]
grid on %[output:148a19c6]
[ENoERDMin,iNoERD]=min(ENoERDSweep);
[EERDMin,iERD]=min(EERDSweep);
fprintf("Lowest energy without ERD: %.2f kWh/m^3 at %.0f%% recovery\n",ENoERDMin,rSweep(iNoERD)*100) %[output:1bab53ed]
fprintf("Lowest energy with ERD: %.2f kWh/m^3 at %.0f%% recovery\n", EERDMin,rSweep(iERD)*100) %[output:535cf06b]

function osmP=osmoticPressure(salinity,T)
n=2;
molarmassNaCl=58.44;
R=0.08314;
C=salinity ./ 1000 ./ molarmassNaCl;
osmP=n.*C.*R.*T;
end 

function rMax60=maxRecovery(pressure,salinity,T)
n=2;
molarmassNaCl=58.44;
R=0.08314;
CMax=pressure ./ (n*R*T);
brineMax=CMax .* molarmassNaCl .* 1000;
rMax60=1-salinity ./ brineMax;
end

function E=energyNoERD(P,r,Eff)
E=(P.*0.0278)./(r.*Eff);
end

function E=energyERD(P,r,Eff,ERDEff)
E=((P.*0.0278)./(r.*Eff)).*((1 - (1-r).*ERDEff));
end




